import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.BbQUUm7J.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md","lastUpdated":1794936786000}'),a={name:"reference/troubleshooting.md"};function n(i,t,s,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Every error the CLI refuses with is a designed signal, not a bug to work around. Grouped by what you were trying to do. Exit codes: <code>0</code> success; non-zero refusal (per-command codes where documented, e.g. <code>tx verify</code> semantics or the MCP execution-mode exit 47).</p><h2 id="install-update" tabindex="-1">Install &amp; update <a class="header-anchor" href="#install-update" aria-label="Permalink to &quot;Install &amp; update&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>furlpay: command not found</code></td><td>npm global bin not on PATH</td><td><code>npm config get prefix</code> → add its bin to PATH, or reinstall with the installer script</td></tr><tr><td>Install script warns about mirrors</td><td>unofficial registry override</td><td>remove the mirror from <code>.npmrc</code>; the script warns rather than proceeding silently</td></tr><tr><td><code>furlpay update</code> stalls</td><td>npm global permissions</td><td>use the installer script (never sudo) or <code>npm config set prefix</code> to a user-writable path</td></tr></tbody></table><h2 id="authentication-credentials" tabindex="-1">Authentication &amp; credentials <a class="header-anchor" href="#authentication-credentials" aria-label="Permalink to &quot;Authentication &amp; credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Device login URL doesn&#39;t open</td><td>headless box</td><td>set <code>FURLPAY_NO_BROWSER=1</code> and open the printed URL anywhere</td></tr><tr><td><code>login --key</code> refused</td><td>secret on argv</td><td>pipe it: `printf &#39;%s&#39; &quot;$KEY&quot;</td></tr><tr><td>Hosted commands 401</td><td>expired session cookie</td><td><code>furlpay login</code> again; the cookie only attaches to furlpay.com over TLS/loopback — check <code>--api-base</code> if you overrode it</td></tr><tr><td><code>credential-less request</code> warning</td><td><code>--api-base</code> pointed at a non-FurlPay host</td><td>by design: cookies never leave the furlpay.com/loopback boundary</td></tr></tbody></table><h2 id="wallets-signing" tabindex="-1">Wallets &amp; signing <a class="header-anchor" href="#wallets-signing" aria-label="Permalink to &quot;Wallets &amp; signing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>Ledger probe finds nothing</td><td>app not open / USB HID permissions</td><td>open the Stellar app on the device; on Linux check udev rules</td></tr><tr><td>&quot;Fail closed without signer&quot; on HLP/perps</td><td>no signer configured</td><td>export <code>HYPERLIQUID_PRIVATE_KEY</code> (or <code>ETH_PRIVATE_KEY</code>) — there is deliberately no simulated fallback</td></tr><tr><td>Order refused: <code>LIVE_EXECUTION_DISABLED</code></td><td><code>FURLPAY_LIVE</code> master gate</td><td>set <code>FURLPAY_LIVE=1</code> <strong>and</strong> have the per-surface credential; the gate is on top of, not instead of, credentials</td></tr><tr><td>Order refused by risk engine</td><td>margin/notional/turnover/peg guard</td><td>read the reason field: peg halts carry <code>PEG_FEED_UNAVAILABLE</code> when the feed (not the peg) is the problem</td></tr></tbody></table><h2 id="mcp-agents" tabindex="-1">MCP agents <a class="header-anchor" href="#mcp-agents" aria-label="Permalink to &quot;MCP agents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>EXECUTION_MODE_REQUIRED</code></td><td>read-only default</td><td>this is the designed default; add <code>--enable-execution</code> + a policy <strong>only</strong> if you intend value movement</td></tr><tr><td>Server exits 47 on <code>--enable-execution</code></td><td>no agent policy on disk</td><td>run <code>furlpay wallet agent-keygen</code> first (recipe 8)</td></tr><tr><td><code>TWO_PHASE_REQUIRED</code></td><td>mutating tool called directly</td><td>preview via <code>furlpay_preview_execution</code>, then <code>furlpay_confirm_execution {executionHash}</code></td></tr><tr><td>Confirm fails after 10 min</td><td>preview TTL expired</td><td>re-preview; hashes are single-use by design</td></tr><tr><td>Tool missing from tools/list</td><td>it is value-moving and you are read-only</td><td>structural absence — see <a href="/furlpay-cli/reference/mcp-tools">MCP tools</a></td></tr></tbody></table><h2 id="network-surfaces" tabindex="-1">Network surfaces <a class="header-anchor" href="#network-surfaces" aria-label="Permalink to &quot;Network surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>tx verify</code> returns <code>UNAVAILABLE</code></td><td>Horizon outage</td><td>an outage is never evidence about the transaction; retry later</td></tr><tr><td><code>solana</code> commands fail with <code>SOLANA_RPC_INSECURE_URL</code></td><td>non-https RPC</td><td>use https endpoints only</td></tr><tr><td><code>INVALID_SOLANA_ADDRESS</code></td><td>not base58 (0/O/I/l present, wrong length)</td><td>validate the address before the call</td></tr><tr><td>Oracle <code>DISAGREEMENT</code> (exit 1)</td><td>sources differ beyond the asset budget</td><td>inspect the printed per-source readings; the CLI refuses to blend disagreeing prices</td></tr><tr><td>Oracle <code>UNAVAILABLE</code> (exit 2)</td><td>no source answered sanely</td><td>check network/egress; nothing is guessed — that is the point</td></tr><tr><td>Pyth provider listed <code>(none)</code></td><td>public Hermes is auth-gated</td><td>configure <code>FURLPAY_PYTH_HERMES_URL</code> + <code>FURLPAY_PYTH_FEED_IDS</code> with a gateway you are authorized to use</td></tr><tr><td>Binance orders refused</td><td>missing consent (no <code>--wallet</code>, non-interactive, no <code>--yes</code>)</td><td>pass <code>--wallet &lt;agent&gt;</code> (mandate gate) or run interactively and confirm</td></tr></tbody></table><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>config validate</code> fails on passphrase</td><td>edited network profile</td><td>passphrases must match the canonical values; restore from defaults</td></tr><tr><td><code>doctor</code> exits non-zero</td><td>API liveness check failed</td><td>follow its report; <code>--output json</code> for scripts</td></tr><tr><td>keystore errors mention locks</td><td>concurrent CLI processes</td><td>the write path is atomic + locked; retry — never delete <code>~/.furlpay</code> to &quot;fix&quot; a lock</td></tr></tbody></table>',14)])])}const g=e(a,[["render",n]]);export{p as __pageData,g as default};
